package bo.com.ganadero.sanidad.application;
import bo.com.ganadero.alertas.application.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.time.OffsetDateTime;import java.util.*;
/** Operación sistema-sistema: no simula un veterinario ni depende de CurrentUser. */
@Service public class ProcesarTratamientosVencidosService{private final JdbcClient jdbc;private final MotorAlertas alertas;public ProcesarTratamientosVencidosService(JdbcClient j,MotorAlertas a){jdbc=j;alertas=a;}@Scheduled(cron="${ganadero.sanidad.cron-tratamientos-vencidos:0 */15 * * * *}")@Transactional public int procesar(){List<Vencida> vencidas=jdbc.sql("select a.id,a.empresa_id,t.animal_id,a.fecha_programada from sanidad.aplicaciones_tratamiento a join sanidad.tratamiento_detalles d on d.id=a.tratamiento_detalle_id join sanidad.tratamientos t on t.id=d.tratamiento_id where a.estado='PENDIENTE' and a.fecha_programada<now() and t.estado='ACTIVO' order by a.fecha_programada for update of a skip locked limit 100").query((r,n)->new Vencida(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),odt(r,4))).list();for(Vencida v:vencidas){jdbc.sql("update sanidad.aplicaciones_tratamiento set estado='ATRASADA',updated_at=now(),version=version+1 where id=:id and estado='PENDIENTE'").param("id",v.id).update();alertas.crearInmediata(new ProgramarAlertaCommand(v.empresa,v.animal,TipoAlerta.TRATAMIENTO_ATRASADO,Instant.now(),"APLICACION_TRATAMIENTO",v.id,Map.of("fechaProgramada",v.fecha.toString())));}return vencidas.size();}private static Instant odt(java.sql.ResultSet r,int c)throws java.sql.SQLException{OffsetDateTime v=r.getObject(c,OffsetDateTime.class);return v==null?null:v.toInstant();}private record Vencida(UUID id,UUID empresa,UUID animal,Instant fecha){}}
